\set ON_ERROR_STOP off
\set QUIET on
SET client_min_messages = notice;

-- ===== utilidades de prueba (propietario) =====
CREATE SCHEMA IF NOT EXISTS t;
GRANT USAGE ON SCHEMA t TO onway_app, onway_platform;
CREATE OR REPLACE FUNCTION t.rec(p_label text, p_ok boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RAISE NOTICE 'RESULT|%|%', CASE WHEN p_ok THEN 'PASS' ELSE 'FAIL' END, p_label; END $$;

CREATE OR REPLACE FUNCTION t.ctx(p_org uuid, p_user uuid, p_role text) RETURNS void LANGUAGE sql AS $$
  SELECT set_config('app.org_id', coalesce(p_org::text,''), true), set_config('app.user_id', coalesce(p_user::text,''), true), set_config('app.role', coalesce(p_role,''), true) $$;
CREATE OR REPLACE FUNCTION t.fails(p_label text, p_stmt text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  BEGIN EXECUTE p_stmt; PERFORM t.rec(p_label, false);
  EXCEPTION WHEN OTHERS THEN PERFORM t.rec(p_label, true); END;
END $$;
CREATE OR REPLACE FUNCTION t.works(p_label text, p_stmt text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  BEGIN EXECUTE p_stmt; PERFORM t.rec(p_label, true);
  EXCEPTION WHEN OTHERS THEN PERFORM t.rec(p_label || '  [' || SQLERRM || ']', false); END;
END $$;
CREATE OR REPLACE FUNCTION t.count_is(p_label text, p_stmt text, p_expected int) RETURNS void LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  BEGIN EXECUTE 'SELECT count(*) FROM (' || p_stmt || ') q' INTO n;
        PERFORM t.rec(p_label || ' (esperado ' || p_expected || ', obtenido ' || n || ')', n = p_expected);
  EXCEPTION WHEN OTHERS THEN PERFORM t.rec(p_label || '  [' || SQLERRM || ']', false); END;
END $$;
CREATE OR REPLACE FUNCTION t.rows_changed(p_label text, p_stmt text, p_expected int) RETURNS void LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  BEGIN EXECUTE p_stmt; GET DIAGNOSTICS n = ROW_COUNT;
        PERFORM t.rec(p_label || ' (esperado ' || p_expected || ', obtenido ' || n || ')', n = p_expected);
  EXCEPTION WHEN OTHERS THEN PERFORM t.rec(p_label || '  [' || SQLERRM || ']', false); END;
END $$;

